-- The two checklists published on 2026-11-17: Taking Feedback That Lands Hard
-- (Feedback) and Making New Friends as an Adult (Making Friends).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-17`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('taking-feedback-that-lands-hard', 'Taking Feedback That Lands Hard', 'Open this after a review, a critique or a note from someone whose opinion matters, when the words keep replaying. It helps you sit with what was said, sort the useful part from the sting, and decide what, if anything, to change.', 'Feedback', '["Write down what was actually said — Getting the words out of your head and onto paper stops them growing in the retelling.", "Wait a day before you reply — A first reaction is usually about the sting, not the substance.", "Underline the one line that stung most — Naming the sharpest part shrinks it to a single sentence you can look at.", "Separate the facts from the tone — Someone can be right about the work and clumsy about how they said it.", "Ask about the part you do not understand — A short question turns a verdict back into a conversation.", "Name the part you would keep — Feedback can be useful in part without being true in whole.", "Pick one thing to change this week — One small change is a response; a full overhaul is a punishment.", "Tell one person you trust about it — Saying it out loud to someone kind takes the private weight off."]'::jsonb, 'as needed', array['Work', 'Self-Esteem', 'Perfectionism']::text[], 1, '2026-11-17T16:00:00+00:00'::timestamptz),
  ('making-new-friends-as-an-adult', 'Making New Friends as an Adult', 'Open this when your days are full but your weekends are quiet, and the friendships you have are far away or faded. It gives you a few repeatable steps for meeting people and, harder than that, turning a pleasant stranger into someone you actually see.', 'Making Friends', '["Go back to the same place twice — Familiar faces come from repetition, not from one good night out.", "Pick something that meets every week — A standing time does the remembering for you.", "Ask one question past the small talk — Moving from the weather to what someone cares about is where a friend starts.", "Name a day, not just an intention — An invitation with a date attached is the one that actually happens.", "Follow up within a week — The gap after a first meeting is where most new friendships quietly end.", "Offer something small and low effort — A walk or a coffee is easier to say yes to than a whole evening out.", "Let it be dull at first — Early friendship is mostly logistics and small talk; depth arrives later.", "Count the near misses as practice — Not everyone you like will have room for a new friend, and that is not about you."]'::jsonb, 'weekly', array['Loneliness', 'Social Anxiety', 'Relationships']::text[], 1, '2026-11-17T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
